param([int[]]$Scenarios=@(1,3,5,10),[int]$BasePort=0)
$ErrorActionPreference='Stop';$repo=Split-Path $PSScriptRoot;$mvn="$env:USERPROFILE\.m2\wrapper\dists\apache-maven-3.9.12-bin\5nmfsn99br87k5d4ajlekdq10k\apache-maven-3.9.12\bin\mvn.cmd";$ff=(Get-ChildItem "$env:TEMP\transcoder-ffmpeg-portable-qa" -Recurse -Filter ffmpeg.exe|Select -First 1).FullName;$fp=(Get-ChildItem "$env:TEMP\transcoder-ffmpeg-portable-qa" -Recurse -Filter ffprobe.exe|Select -First 1).FullName;$video=Join-Path $env:TEMP 'youtube-unit-qa-videos\v480.mp4';$root=Join-Path $env:TEMP ('youtube-unit-final-'+[guid]::NewGuid());New-Item -ItemType Directory -Force $root|Out-Null
foreach($n in $Scenarios){$port=if($BasePort){$BasePort+$n}else{Get-Random -Minimum 20000 -Maximum 40000};$dir=Join-Path $root "clients-$n";New-Item -ItemType Directory -Force $dir|Out-Null;$data=Join-Path $dir data;New-Item -ItemType Directory -Force $data|Out-Null;$row=[ordered]@{clientsRequested=$n;clientsStarted=0;requestsAttempted=0;responsesReceived=0;http202=0;http429=0;completed=0;failed=0;downloadsValid=0;peakActiveObserved=0;result='FAIL';reason=$null};$psi=[Diagnostics.ProcessStartInfo]::new('cmd.exe',"/c `"$mvn`" exec:java");$psi.WorkingDirectory=$repo;$psi.UseShellExecute=$false;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$psi.EnvironmentVariables['PORT']="$port";$psi.EnvironmentVariables['TRANSCODER_DATA_DIR']=$data;$psi.EnvironmentVariables['FFMPEG_BIN']=$ff;$psi.EnvironmentVariables['FFPROBE_BIN']=$fp;$api=[Diagnostics.Process]::new();$api.StartInfo=$psi;$api.Start();try{$ready=$false;for($i=0;$i-lt 180;$i++){try{$h=Invoke-WebRequest "http://127.0.0.1:$port/health" -UseBasicParsing -TimeoutSec 2;$j=Invoke-WebRequest "http://127.0.0.1:$port/jobs" -UseBasicParsing -TimeoutSec 2;if($h.StatusCode-eq 200-and([string]$j.Content).Trim()-eq '[]'){$ready=$true;break}}catch{};Start-Sleep -Milliseconds 500};if(!$ready){throw 'startup timeout'};$gate=Join-Path $dir START;$jobs=1..$n|%{Start-Job -ArgumentList $port,$video,$gate,$_ -ScriptBlock {param($p,$f,$g,$i)while(!(Test-Path $g)){Start-Sleep -Milliseconds 10};try{$s=[Diagnostics.Stopwatch]::StartNew();$raw=& curl.exe -sS -X POST -w "`n__STATUS:%{http_code}" -F "file=@$f;type=video/mp4" -F "origin=cliente-$i" -F 'permission=sintetico' -F 'profiles=360p' "http://127.0.0.1:$p/videos" 2>&1;$txt=$raw-join "`n";$status=[regex]::Match($txt,'__STATUS:(\d+)').Groups[1].Value;$body=($txt-split "`n__STATUS:")[0];[pscustomobject]@{clientId=$i;status=$status;body=$body;durationMs=$s.ElapsedMilliseconds;error=$null}}catch{[pscustomobject]@{clientId=$i;status=0;body='';durationMs=0;error=$_.Exception.Message}}}};New-Item $gate -ItemType File|Out-Null;$row.clientsStarted=$jobs.Count;$row.requestsAttempted=$n;$done=$jobs|Wait-Job -Timeout 120;if($done.Count-ne$n){throw 'client timeout'};$res=$done|Receive-Job;$res|ConvertTo-Json -Depth 5|Set-Content (Join-Path $dir clients.json);$row.responsesReceived=$res.Count;$ids=@();foreach($r in $res){if($r.status-eq '202'){$row.http202++;$o=$r.body|ConvertFrom-Json;$ids+=$o.job.id}elseif($r.status-eq '429'){$row.http429++}};if($res.Count-ne$n-or$ids.Count-ne$row.http202-or($ids|Select -Unique).Count-ne$ids.Count){throw 'request/id mismatch'};$states=@{};for($t=0;$t-lt 120;$t++){foreach($id in $ids){if(!$states.ContainsKey($id)){$states[$id]=(Invoke-RestMethod "http://127.0.0.1:$port/jobs/$id").status}};$active=@($states.Values|? {$_-in @('QUEUED','PROCESSING')}).Count;if($active-gt$row.peakActiveObserved){$row.peakActiveObserved=$active};if($states.Count-eq$ids.Count-and$active-eq 0){break};Start-Sleep -Milliseconds 500};$row.completed=@($states.Values|? {$_-eq 'COMPLETED'}).Count;$row.failed=@($states.Values|? {$_-eq 'FAILED'}).Count;foreach($id in $ids){$q=Invoke-RestMethod "http://127.0.0.1:$port/jobs/$id";foreach($o in $q.outputs){$dst=Join-Path $dir "$id-$($o.profile).mp4";Invoke-WebRequest "http://127.0.0.1:$port/arquivos/$($o.id)" -OutFile $dst;&$fp -v error $dst 2>$null;if($LASTEXITCODE-eq 0){$row.downloadsValid++}}};if($row.completed-eq$row.http202-and$row.failed-eq 0-and$row.downloadsValid-ge$row.completed-and$row.peakActiveObserved-le 3){$row.result='PASS'}else{throw 'criteria failed'}}catch{$row.reason=$_.Exception.Message}finally{$row|ConvertTo-Json|Set-Content (Join-Path $dir summary.json);$jobs|Remove-Job -Force -ErrorAction SilentlyContinue;if(!$api.HasExited){taskkill /PID $api.Id /T /F 2>$null|Out-Null}};$row|ConvertTo-Json -Compress;if($row.result-ne 'PASS'){exit 1}}
